def gen(rng):
    def fmt(c):
        return f"{len(c)}\n" + ' '.join(map(str, c))
    tests = [fmt([4, 9, 2, 7]), fmt([5, 5, 10, 1, 5]), fmt([100]), fmt([1, 1]), fmt([3, 8]), fmt([2, 2, 2])]
    for n in range(2, 9):
        for _ in range(2):
            tests.append(fmt([rng.randint(1, 10) for _ in range(n)]))
    for n in (4, 5, 6, 7):
        tests.append(fmt([rng.randint(1, 3) for _ in range(n)]))
    N = 2 * 10**5
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N - 1)]))
    tests.append(fmt([10**9] * N))
    tests.append(fmt(sorted(rng.randint(1, 10**9) for _ in range(N))))
    return tests

